  { selected: false, size: 63 },
)

/** Each glyph is framed by its own window onto the 10.svg artboard. */
const VIEW_BOX: Record<ActivityMood, { rest: string; sel: string }> = {
  soso: { rest: '0.0 0.0 401.625 401.625', sel: '0.0 465.375 401.625 401.625' },
  good: { rest: '529.125 0.0 401.625 401.625', sel: '529.125 465.375 401.625 401.625' },
  great: { rest: '1058.25 0.0 401.625 401.625', sel: '1058.25 465.375 401.625 401.625' },
}

const viewBox = computed((): string =>
  props.selected ? VIEW_BOX[props.mood].sel : VIEW_BOX[props.mood].rest,
)
